#!/usr/bin/env python3
# DAY307 paso 2 — fuera el calculo de los 5 rasgos DDoS v2 en populate_ml_defender_features.
# En produccion ring_consumer (populate_protobuf_event, unica llamada con la foto siempre presente) los
# sobrescribe con la foto tomada en el lock (ddos_v2_flow_snapshot): el calculo sobre la copia (una pasada por
# all_lengths para la media y un std::map reconstruido para la entropia, en cada evento) se tiraba siempre.
#  - ml_defender_features.cpp: fuera extract_ddos_features y extract_ddos_packet_size_entropy; populate ya no
#    toca ddos_embedded.
#  - ml_defender_features.hpp: fuera sus declaraciones; comentario de la foto actualizado.
#  - test_ddos_flow_snap.cpp: la referencia de lote se calcula en el test con las mismas operaciones en float.
#  - test_ring_consumer_protobuf.cpp: comprueba que populate NO toca ddos_embedded y mira los rasgos DDoS en la
#    foto (ddos_v2_flow_snapshot), que es su unica fuente.
# Valida TODO antes de escribir NADA (sha256 de partida y de llegada, anclas unicas). Reconoce "ya aplicado".
# Uso (Mac, raiz del repo): python3 scripts/flow_expiry/d307_paso2_sin_ddos_lote.py --check | --apply
import hashlib, os, sys
EDITS = {'sniffer/src/userspace/ml_defender_features.cpp': {'antes': '0fcc3c0856ad3773e53d5b566160c6b122005ac321892d4a7ac12544ac447b77', 'despues': 'e41665169ed35c146521080c57b6d03389d3611a7167678c952a105859c6855f', 'rep': [('void MLDefenderExtractor::extract_ddos_features(\n    const FlowStatistics& flow,\n    ::protobuf::DDoSFeatures* ddos) const {\n\n    ddos->set_syn_ack_ratio(extract_ddos_syn_ack_ratio(flow));\n    ddos->set_packet_size_entropy(extract_ddos_packet_size_entropy(flow));\n    ddos->set_flow_completion_rate(extract_ddos_flow_completion_rate(flow));\n    // [DDOS-V2-D286] contrato v2 (8 rasgos, solo trafico entrante)\n    ddos->set_mean_packet_size(calculate_mean(flow.all_lengths));\n    ddos->set_flow_packet_count(static_cast<float>(flow.get_total_packets()));\n}\n\n', '// [D307-PASO2] Los 5 rasgos DDoS v2 de flujo solo los calcula ddos_v2_flow_snapshot (foto en el lock del shard,\n// O(k)); ring_consumer los escribe en el protobuf. El antiguo extract_ddos_features los recalculaba sobre la copia\n// recorriendo all_lengths en cada evento, y ring_consumer los sobrescribia siempre con la foto.\n\n'), ('float MLDefenderExtractor::extract_ddos_packet_size_entropy(const FlowStatistics& flow) const {\n    // Packet size entropy: DDoS often has uniform packet sizes (low entropy)\n    // Normal traffic: varied sizes (high entropy)\n    return calculate_entropy(flow.all_lengths);\n}\n\n', ''), ('    // Extract DDoS features (10 features)\n    auto* ddos = net_features->mutable_ddos_embedded();\n    extract_ddos_features(flow, ddos);\n\n', '    // DDoS: ring_consumer escribe los 5 rasgos de flujo desde la foto (ddos_v2_flow_snapshot) [D307-PASO2]\n\n')]}, 'sniffer/include/ml_defender_features.hpp': {'antes': '4a191ac076c46ba98066f817c625f93f1a15991030583b946acbc51c1eb18ee8', 'despues': '2c053e76d6e20b8170a53c1af382cf020a6c8fb17cc6327ec6c0a420249b50ec', 'rep': [('    /**\n     * Extract Level 2 - DDoS Features (10 features)\n     * Detects volumetric attacks, SYN floods, amplification attacks\n     */\n    void extract_ddos_features(\n        const FlowStatistics& flow,\n        ::protobuf::DDoSFeatures* ddos) const;\n\n', ''), ('    float extract_ddos_packet_size_entropy(const FlowStatistics& flow) const;\n', ''), ('    // flow_completion_rate, flow_packet_count, mean_packet_size, packet_size_entropy) con las\n    // mismas formulas que extract_ddos_features, sobre los estadisticos incrementales del flujo.\n', '    // flow_completion_rate, flow_packet_count, mean_packet_size, packet_size_entropy), sobre los\n    // estadisticos incrementales del flujo. Unica fuente de esos 5 rasgos [D307-PASO2].\n')]}, 'sniffer/tests/test_ddos_flow_snap.cpp': {'antes': '34ddb24a74b6dc3253887f71e6919c2f2112dcc84c3b380354c8f22bed672d70', 'despues': '59bde61282474a4eed00b7d57a38233ec2a041345d95d5b84a5110eb61ac03d0', 'rep': [('    ::protobuf::DDoSFeatures lote;\n    ext.extract_ddos_features(f, &lote);\n\n    comparar(caso, "syn_ack_ratio", foto.syn_ack_ratio, lote.syn_ack_ratio());\n    comparar(caso, "flow_completion_rate", foto.flow_completion_rate, lote.flow_completion_rate());\n    comparar(caso, "flow_packet_count", foto.flow_packet_count, lote.flow_packet_count());\n    comparar(caso, "mean_packet_size", foto.mean_packet_size, lote.mean_packet_size());\n    comparar(caso, "packet_size_entropy", foto.packet_size_entropy, lote.packet_size_entropy());\n', '    // [D307-PASO2] Referencia de lote calculada aqui sobre la copia, con las mismas operaciones en float que\n    // usaba extract_ddos_features (retirado): calculate_mean y calculate_entropy sobre all_lengths.\n    const float n_f = static_cast<float>(f.all_lengths.size());\n    float ent = 0.0f;\n    for (const auto& [v, c] : hist) {\n        (void)v;\n        const float p = static_cast<float>(c) / n_f;\n        if (p > 0.0f) ent -= p * std::log2(p);\n    }\n    const float ack1 = static_cast<float>(f.ack_count) + 1.0f;\n    const float sar = std::min((ack1 != 0.0f) ? static_cast<float>(f.syn_count) / ack1 : 0.0f, 10.0f);\n    const float fcr = (f.syn_count > 0 && f.ack_count > 0 && f.fin_count > 0) ? 1.0f\n                    : (f.syn_count > 0 && f.ack_count > 0) ? 0.5f : 0.0f;\n    const float media = f.all_lengths.empty() ? 0.0f : static_cast<float>(suma) / n_f;\n\n    comparar(caso, "syn_ack_ratio", foto.syn_ack_ratio, sar);\n    comparar(caso, "flow_completion_rate", foto.flow_completion_rate, fcr);\n    comparar(caso, "flow_packet_count", foto.flow_packet_count, static_cast<float>(f.get_total_packets()));\n    comparar(caso, "mean_packet_size", foto.mean_packet_size, media);\n    comparar(caso, "packet_size_entropy", foto.packet_size_entropy, ent);\n'), ('#include <random>\n', '#include <random>\n#include <algorithm>  // [D307-PASO2]\n#include <cmath>      // [D307-PASO2]\n'), ('// el hilo del anillo) tiene que dar EXACTAMENTE (bit a bit) lo mismo que la extraccion de lote de\n// produccion (extract_ddos_features sobre la copia del flujo). Sin agregador: source_ip_dispersion\n', '// el hilo del anillo) tiene que dar EXACTAMENTE (bit a bit) lo mismo que el calculo de lote sobre la\n// copia del flujo (formulas de calculate_mean/calculate_entropy, DAY307). Sin agregador: source_ip_dispersion\n')]}, 'sniffer/tests/test_ring_consumer_protobuf.cpp': {'antes': '0e8a2ba978e342a80bf32b05f736d14c7ce43d4650e435b1635457ecc9025f80', 'despues': 'a50e77606631bd7f45d8e22f21edef3173e356dd54593eaad2d17a8e7b6eb52a', 'rep': [('    // DDoS Features (10)\n    ASSERT_TRUE(net_features.has_ddos_embedded()) << "DDoS features must be populated";\n    const auto& ddos = net_features.ddos_embedded();\n\n    // [DDOS-V1-RETIRE-D306] rasgos de flujo del contrato v2 que rellena el extractor\n    EXPECT_GE(ddos.syn_ack_ratio(), 0.0f) << "SYN/ACK ratio populated";\n    EXPECT_GE(ddos.packet_size_entropy(), 0.0f) << "Packet size entropy populated";\n    EXPECT_GT(ddos.flow_packet_count(), 0.0f) << "Flow packet count populated";\n    EXPECT_GT(ddos.mean_packet_size(), 0.0f) << "Mean packet size populated";\n\n    std::cout << "✅ DDoS Features: "\n              << "syn_ack=" << ddos.syn_ack_ratio() << " "\n              << "pkts=" << ddos.flow_packet_count() << " "\n              << "entropy=" << ddos.packet_size_entropy() << "\\n";\n\n', '    // DDoS (contrato v2) [D307-PASO2]: populate ya no rellena ddos_embedded; los 5 rasgos de flujo salen de la\n    // foto en lock (ddos_v2_flow_snapshot), que ring_consumer escribe en el protobuf. Se comprueban sobre la foto.\n    EXPECT_FALSE(net_features.has_ddos_embedded()) << "populate no debe tocar ddos_embedded";\n    DdosFlowSnap snap{};\n    mgr.with_flow_stats(key, [&](const auto& fs) { snap = ml_extractor_->ddos_v2_flow_snapshot(fs); });\n    ASSERT_TRUE(snap.valid) << "La foto DDoS debe existir";\n    EXPECT_GE(snap.syn_ack_ratio, 0.0f) << "SYN/ACK ratio populated";\n    EXPECT_GE(snap.packet_size_entropy, 0.0f) << "Packet size entropy populated";\n    EXPECT_GT(snap.flow_packet_count, 0.0f) << "Flow packet count populated";\n    EXPECT_GT(snap.mean_packet_size, 0.0f) << "Mean packet size populated";\n\n    std::cout << "✅ DDoS Features (foto): "\n              << "syn_ack=" << snap.syn_ack_ratio << " "\n              << "pkts=" << snap.flow_packet_count << " "\n              << "entropy=" << snap.packet_size_entropy << "\\n";\n\n'), ('    if (net_features.has_ddos_embedded()) populated++;\n', '    if (snap.valid) populated++;  // [D307-PASO2] DDoS desde la foto\n'), ('    const auto& ddos = proto_event.network_features().ddos_embedded();\n\n    // SYN/ACK ratio should be calculated from TCP flags\n    EXPECT_GT(ddos.syn_ack_ratio(), 0.0f) << "SYN/ACK ratio must be calculated";\n\n    // Flow completion rate should reflect complete handshake\n    EXPECT_GT(ddos.flow_completion_rate(), 0.0f) << "Flow completion must be detected";\n\n    std::cout << "✅ TCP Features: syn_ack_ratio=" << ddos.syn_ack_ratio()\n              << " completion=" << ddos.flow_completion_rate() << "\\n";\n', '    // [D307-PASO2] los rasgos DDoS v2 salen de la foto en lock, no de populate\n    DdosFlowSnap snap{};\n    mgr.with_flow_stats(key, [&](const auto& fs) { snap = ml_extractor_->ddos_v2_flow_snapshot(fs); });\n    ASSERT_TRUE(snap.valid);\n\n    // SYN/ACK ratio should be calculated from TCP flags\n    EXPECT_GT(snap.syn_ack_ratio, 0.0f) << "SYN/ACK ratio must be calculated";\n\n    // Flow completion rate should reflect complete handshake\n    EXPECT_GT(snap.flow_completion_rate, 0.0f) << "Flow completion must be detected";\n\n    std::cout << "✅ TCP Features: syn_ack_ratio=" << snap.syn_ack_ratio\n              << " completion=" << snap.flow_completion_rate << "\\n";\n'), ('    const auto& ddos = proto_event.network_features().ddos_embedded();\n\n    // [DDOS-V1-RETIRE-D306] symmetry', '    // [D307-PASO2] los rasgos DDoS v2 salen de la foto en lock, no de populate\n    DdosFlowSnap snap{};\n    mgr.with_flow_stats(key, [&](const auto& fs) { snap = ml_extractor_->ddos_v2_flow_snapshot(fs); });\n    ASSERT_TRUE(snap.valid);\n\n    // [DDOS-V1-RETIRE-D306] symmetry'), ('    EXPECT_FLOAT_EQ(ddos.flow_packet_count(), 15.0f) << "v2 flow_packet_count = fwd + bwd";\n', '    EXPECT_FLOAT_EQ(snap.flow_packet_count, 15.0f) << "v2 flow_packet_count = fwd + bwd";\n'), ('              << " flow_packet_count=" << ddos.flow_packet_count() << "\\n";\n', '              << " flow_packet_count=" << snap.flow_packet_count << "\\n";\n')]}}

def die(m):
    print("ABORTA: " + m)
    sys.exit(1)

def sha_b(b):
    return hashlib.sha256(b).hexdigest()

def sha(p):
    return sha_b(open(p, "rb").read())

if len(sys.argv) != 2 or sys.argv[1] not in ("--check", "--apply"):
    die("uso: --check | --apply")
APPLY = sys.argv[1] == "--apply"
if not (os.path.isfile("Makefile") and os.path.isdir("sniffer/src/userspace")):
    die("no estoy en la raiz del repo")
if all(sha(p) == e["despues"] for p, e in EDITS.items()):
    print("[YA APLICADO] paso 2 hecho. Nada que hacer.")
    sys.exit(0)
nuevos = {}
for p, e in EDITS.items():
    s = sha(p)
    if s != e["antes"]:
        die(f"{p} sha256 {s} no es el de partida (estado mixto o fichero cambiado)")
    t = open(p, encoding="utf-8").read()
    for a, b in e["rep"]:
        if t.count(a) != 1:
            die(f"{p}: ancla x{t.count(a)} (esperado 1): {a[:60]!r}")
        t = t.replace(a, b)
    if sha_b(t.encode("utf-8")) != e["despues"]:
        die(f"{p}: el resultado no tendria el sha256 esperado")
    nuevos[p] = (t, len(e["rep"]))
for p, (_, n) in nuevos.items():
    print(f"[OK] editar {p} ({n} bloques)")
if not APPLY:
    print("[CHECK] todo valida; nada escrito. Repite con --apply.")
    sys.exit(0)
for p, (t, _) in nuevos.items():
    tmp = p + ".d307tmp"
    with open(tmp, "w", encoding="utf-8") as f:
        f.write(t)
    os.replace(tmp, p)
if any(sha(p) != e["despues"] for p, e in EDITS.items()):
    die("verificacion posterior fallida")
print("[APLICADO] paso 2.")
